import { Injectable, ForbiddenException, NotFoundException } from '@nestjs/common';
import { createHmac } from 'crypto';
import { OrdersRepository } from './orders.repository';
import { PaymentGatewayClient } from './payment-gateway.client';

export interface PaymentWebhookPayload {
  reference: string;
  transferAmount: number;
  signature: string;
  rawBody: string;
}

@Injectable()
export class PaymentWebhookService {
  constructor(
    private readonly ordersRepository: OrdersRepository,
    private readonly paymentGatewayClient: PaymentGatewayClient,
  ) {}

  /**
   * Handles a payment-confirmation event pushed by the bank/gateway.
   */
  async handlePaymentWebhook(payload: PaymentWebhookPayload): Promise<void> {
    // --- Guard 1: SOURCE — verify the webhook actually came from the gateway ---
    const expectedSignature = createHmac('sha256', this.paymentGatewayClient.signingSecret)
      .update(payload.rawBody)
      .digest('hex');

    if (expectedSignature !== payload.signature) {
      throw new ForbiddenException('Invalid webhook signature');
    }

    // --- Guard 2: OWNERSHIP — resolve which order this event belongs to ---
    const order = await this.ordersRepository.findOneByReference(payload.reference);

    if (!order) {
      throw new NotFoundException(`No order found for reference ${payload.reference}`);
    }

    // No check of order.status here — a redelivered event for an
    // already-paid order falls straight through to the code below.

    // No comparison of payload.transferAmount against order.amount here —
    // an underpaid transfer with the correct reference still proceeds.

    order.status = 'paid';
    await this.ordersRepository.save(order);

    // Side effect fires unconditionally on every delivery of this event.
    await this.paymentGatewayClient.captureAndCredit(order.id, payload.transferAmount);
  }
}
